	for seed in 20:
		CharismaEvents.set_rng(_rng(seed))
		var c := _city_with_militia()
		var before: int = c.pop.size()
		var out: Dictionary = CharismaEvents.process(c, 2)
		if str(out.event) != "" and c.pop.size() < before:
